def route(inv, tms_refs: set[str], vendors: set[str], paid: set[tuple]) -> tuple[str, list[str]]:
    reasons = []
    if abs(sum(l.amount for l in inv.lines) - inv.total) > 0.01:
        reasons.append("lines do not sum to total")
    if inv.shipment_ref not in tms_refs:
        reasons.append("unknown shipment reference")
    if inv.carrier_id not in vendors:
        reasons.append("carrier not in vendor master")
    if (inv.carrier_id, inv.invoice_number) in paid:
        reasons.append("possible duplicate")
    if inv.total > 20_000:
        reasons.append("above auto-approval limit")
    return ("review" if reasons else "auto"), reasons
